}

/* Style Khusus untuk Menu Aktif */
.nav-item.active > .nav-link {
  background: #ffffff;
  color: #161616;
  box-shadow: 0 0 18px rgba(255,255,255,0.55), 0 6px 14px rgba(0,0,0,0.25);
}

.nav-item.active > .nav-link i:first-child,
.nav-item.active > .nav-link .link-text {
