/* Indikator Garis Kiri untuk Menu Aktif */
.nav-item.active > .nav-link::before {
  content: "";
  position: absolute;
  left: -14px;
  top: 8px;
  bottom: 8px;
  width: 4px;
  border-radius: 4px;
  background: #ffffff;
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.9);
}

.nav-link i:first-child {
  font-size: 20px;
  min-width: 24px;
  text-align: center;
  margin-right: 12px;
  transition: color 0.25s ease;
}

.link-text {
  font-size: 14px;
  font-weight: 500;
  flex: 1;
  transition: opacity 0.2s ease;
}

.arrow {
  font-size: 16px;
  transition: transform 0.3s ease, opacity 0.2s ease;
}

.nav-item.open .arrow {
  transform: rotate(180deg);
}

.sidebar.collapsed .link-text,
.sidebar.collapsed .arrow {
  opacity: 0;
  pointer-events: none;
}

/* --- SUBMENU (EXPANDABLE ACCORDION) --- */
.submenu {
  list-style: none;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  padding-left: 36px;
}

.nav-item.open .submenu {
  max-height: 220px;
}

.sidebar.collapsed .submenu {
  display: none;
}

.submenu li a {
  display: block;
  padding: 8px 10px;
