.submenu li a::before {
  content: '';
  position: absolute;
  left: -12px;
  top: 50%;
  transform: translateY(-50%);
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.35);
  transition: background 0.2s ease;
}

.submenu li a:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.08);
  padding-left: 14px;
