/* Footer Sidebar */
.sidebar-footer {
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
}

.logout:hover {
  background: rgba(239, 68, 68, 0.2);
  color: #fca5a5;
}

/* --- KONTEN UTAMA --- */
.main-content {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.glass-card {
  width: 100%;
  max-width: 650px;
  padding: 40px;
  background: rgba(255, 255, 255, 0.03);
  -webkit-backdrop-filter: blur(8px);
          backdrop-filter: blur(8px);
  border: 1.5px solid rgba(255, 255, 255, 0.35);
  border-radius: 26px;
  box-shadow: 0 24px 48px rgba(0,0,0,0.35), inset 0 1px 1px rgba(255,255,255,0.4);
}

.glass-card h1 {
  font-size: 24px;
  margin-bottom: 12px;
  letter-spacing: -0.5px;
}

.glass-card p {
  color: rgba(255,255,255,0.8);
  line-height: 1.6;
  font-size: 15px;
