const sidebar = document.getElementById('sidebar');
const toggleBtn = document.getElementById('toggle-btn');
const submenuToggles = document.querySelectorAll('.submenu-toggle');

// 1. Expand / Collapse seluruh Sidebar
toggleBtn.addEventListener('click', () => {
  sidebar.classList.toggle('collapsed');

  // Tutup semua submenu saat sidebar diciutkan agar rapi
  if (sidebar.classList.contains('collapsed')) {
    document.querySelectorAll('.nav-item.open').forEach((item) => {
      item.classList.remove('open');
    });
  }
});

// 2. Expand / Collapse tiap Submenu (Accordion)
submenuToggles.forEach((toggle) => {
  toggle.addEventListener('click', () => {
    const parentItem = toggle.parentElement;

    // Jika sidebar sedang ciut, otomatis buka sidebar terlebih dahulu
    if (sidebar.classList.contains('collapsed')) {
      sidebar.classList.remove('collapsed');
    }

    // Tutup submenu lain yang sedang terbuka
    document.querySelectorAll('.nav-item.has-submenu').forEach((item) => {
      if (item !== parentItem) {
        item.classList.remove('open');
      }
    });

    // Buka/tutup submenu yang diklik
    parentItem.classList.toggle('open');
  });
});

// 3. Interaksi klik menu utama untuk state aktif
document.querySelectorAll('.nav-list > .nav-item').forEach((item) => {
  const link = item.querySelector('.nav-link');
  link.addEventListener('click', (e) => {
    if (item.classList.contains('has-submenu')) return;

    document.querySelectorAll('.nav-list > .nav-item').forEach((el) => {
      el.classList.remove('active');
    });
    item.classList.add('active');
  });
});

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: 'Plus Jakarta Sans', sans-serif;
}

body {
  min-height: 100vh;
  background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 50%, #311042 100%);
  color: #f8fafc;
  overflow-x: hidden;
}

/* Dekorasi Cahaya Latar Belakang agar Efek Glassmorphism Terlihat Jelas */
body::before,
body::after {
  content: '';
  position: fixed;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  filter: blur(90px);
  z-index: -1;
}

body::before {
  background: rgba(56, 189, 248, 0.35);
  top: -60px;
  left: -60px;
}

body::after {
  background: rgba(192, 132, 252, 0.35);
  bottom: -60px;
  right: 10%;
}

.container {
  display: flex;
  min-height: 100vh;
  padding: 16px;
  gap: 20px;
}

/* --- SIDEBAR GLASSMORPHISM --- */
.sidebar {
  width: 260px;
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 20px;
  padding: 20px 14px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25);
  position: relative;
}

/* Mode Sidebar Tertutup (Collapsed) */
.sidebar.collapsed {
  width: 78px;
}

/* Header Sidebar */
.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.logo {
  display: flex;
  align-items: center;
  gap: 12px;
  overflow: hidden;
  white-space: nowrap;
}

.logo i {
  font-size: 28px;
  color: #38bdf8;
  min-width: 32px;
  text-align: center;
}

.logo-text {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.5px;
  transition: opacity 0.25s ease;
}

.sidebar.collapsed .logo-text {
  opacity: 0;
  pointer-events: none;
}

/* Tombol Toggle Sidebar */
.toggle-btn {
  position: absolute;
  right: -14px;
  top: 26px;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #38bdf8;
  color: #0f172a;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 18px;
  box-shadow: 0 4px 12px rgba(56, 189, 248, 0.4);
  transition: transform 0.35s ease;
}

.sidebar:not(.collapsed) .toggle-btn {
  transform: rotate(180deg);
}

/* Daftar Menu */
.nav-list {
  list-style: none;
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
}

.nav-list::-webkit-scrollbar {
  width: 4px;
}
.nav-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 4px;
}

.nav-link {
  display: flex;
  align-items: center;
  padding: 12px;
  border-radius: 12px;
  color: #cbd5e1;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.25s ease;
  white-space: nowrap;
  position: relative;
}

.nav-link:hover,
.nav-item.active > .nav-link,
.nav-item.open > .nav-link {
  background: rgba(255, 255, 255, 0.14);
  color: #ffffff;
}

.nav-link i:first-child {
  font-size: 22px;
  min-width: 26px;
  text-align: center;
  margin-right: 14px;
  transition: color 0.25s ease;
}

.nav-item.active > .nav-link i:first-child,
.nav-item.open > .nav-link i:first-child {
  color: #38bdf8;
}

.link-text {
  font-size: 14px;
  font-weight: 500;
  flex: 1;
  transition: opacity 0.2s ease;
}

.arrow {
  font-size: 18px;
  transition: transform 0.3s ease, opacity 0.2s ease;
}

.nav-item.open .arrow {
  transform: rotate(180deg);
}

.sidebar.collapsed .link-text,
.sidebar.collapsed .arrow {
  opacity: 0;
  pointer-events: none;
}

/* --- SUBMENU (EXPANDABLE) --- */
.submenu {
  list-style: none;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  padding-left: 42px;
}

.nav-item.open .submenu {
  max-height: 250px;
}

.sidebar.collapsed .submenu {
  display: none;
}

.submenu li a {
  display: block;
  padding: 9px 12px;
  margin-top: 4px;
  font-size: 13px;
  color: #94a3b8;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
  position: relative;
}

.submenu li a::before {
  content: '';
  position: absolute;
  left: -14px;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.25);
  transition: background 0.2s ease;
}

.submenu li a:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.08);
  padding-left: 16px;
}

.submenu li a:hover::before {
  background: #38bdf8;
}

/* Footer Sidebar */
.sidebar-footer {
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.logout:hover {
  background: rgba(239, 68, 68, 0.2);
  color: #fca5a5;
}

/* --- KONTEN UTAMA --- */
.main-content {
  flex: 1;
  display: flex;
  align-items: flex-start;
}

.glass-card {
  width: 100%;
  padding: 32px;
  background: rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;
}

.glass-card h1 {
  font-size: 24px;
  margin-bottom: 10px;
}

.glass-card p {
  color: #cbd5e1;
  line-height: 1.6;
  font-size: 15px;
}

const sidebar = document.getElementById('sidebar');
const toggleBtn = document.getElementById('toggle-btn');
const submenuToggles = document.querySelectorAll('.submenu-toggle');

// 1. Expand / Collapse seluruh Sidebar
toggleBtn.addEventListener('click', () => {
  sidebar.classList.toggle('collapsed');

  // Tutup semua submenu saat sidebar dikecilkan agar rapi
  if (sidebar.classList.contains('collapsed')) {
    document.querySelectorAll('.nav-item.open').forEach((item) => {
      item.classList.remove('open');
    });
  }
});

// 2. Expand / Collapse tiap Submenu (Accordion)
submenuToggles.forEach((toggle) => {
  toggle.addEventListener('click', () => {
    const parentItem = toggle.parentElement;

    // Jika sidebar sedang mengecil, otomatis buka sidebar terlebih dahulu
    if (sidebar.classList.contains('collapsed')) {
      sidebar.classList.remove('collapsed');
    }

    // Tutup submenu lain yang sedang terbuka
    document.querySelectorAll('.nav-item.has-submenu').forEach((item) => {
      if (item !== parentItem) {
        item.classList.remove('open');
      }
    });

    // Buka/tutup submenu yang diklik
    parentItem.classList.toggle('open');
  });
});

