/* ───────────────────────── tank engine (hook) ─────────────────────────
   Simulation lives in refs + Framer Motion values, so fish/food/water move
   at 60fps without re-rendering React. Only spawn/removal of transient
   effects (bubbles, droplets, ripples, food) touches React state.        */
function useTankEngine(cardRef, plan, yearly, reduce) {
  const ref = useRef(null);
  if (!ref.current) {
    const fish = plan.fish.map((c, i) => {
      const K = CREATURES[c.t];
      return {
        id: i, type: c.t, a: c.a, b: c.b, w: c.w, h: c.w * K.r, C: K.C,
        X: rnd(20, 240), Y: 9999, vx: (Math.random() < 0.5 ? -1 : 1) * 40, vy: 0, tx: 0, ty: 0, t: 0,
        face: 1, fs: 1, sp: K.sp * (c.t === "tetra" || c.t === "clown" ? rnd(1, 1.55) : 1),
        cur: c.t !== "whale" && Math.random() < 0.65, depth: c.z ?? (c.t === "whale" ? 0.55 : c.t === "jelly" ? 0.9 : rnd(0.05, 1)), ph: rnd(0, 6), off: [rnd(-35, 35), rnd(-25, 25)], g: c.g,
        mv: { x: motionValue(0), y: motionValue(0), rot: motionValue(0), op: motionValue(0), pop: motionValue(1), flip: motionValue(1) },
      };
    });
    let lead = null;
    fish.forEach((f) => { if (f.g) { if (!lead) lead = f; else f.lead = lead; } });
    ref.current = { W: 0, H: 0, Lc: 0, Lv: 0, Lt: 0, nid: 0, cur: { a: false, x: 0, y: 0 }, foods: [], fish, water: motionValue(0) };
  }
  const s = ref.current;
  const [foods, setFoods] = useState([]);
  const [fx, setFx] = useState([]);
  const inView = useInView(cardRef, { amount: 0.25, once: true });
  const level = (y) => Math.min(0.92, plan.base + (y ? 0.08 : 0));

  const push = (e) => setFx((a) => [...a.slice(-45), { id: ++s.nid, ...e }]);
  const drop = useCallback((id) => setFx((a) => a.filter((e) => e.id !== id)), []);
  const bubble = (x, y) => {
    const wh = s.Lc * s.H; if (wh < 80 || reduce) return;
    const rise = Math.max(20, y - (s.H - wh) - 4);
    push({ k: "b", x, y, z: rnd(4, 11), dx: rnd(-9, 9), rise, dur: rise * 0.02 + 0.3 });
  };
  const feed = (x, y) => {
    if (s.Lc * s.H < 100) return;
    const surf = s.H - s.Lc * s.H;
    push({ k: "r", x, y: surf });
    for (let k = 0; k < 4; k++) {
      const px = clamp(x + rnd(-13, 13), 10, s.W - 10), py = Math.max(y, surf) + rnd(0, 8);
      s.foods.push({ id: ++s.nid, x: px, y: py, mx: motionValue(px), my: motionValue(py), vy: rnd(26, 42), ph: rnd(0, 6), age: 0, col: k % 2 ? "#fb7185" : "#fbbf24" });
    }
    setFoods([...s.foods]);
  };
  const scatter = (power = 1) => s.fish.forEach((f) => { f.vx += rnd(-300, 300) * power; f.vy += rnd(-210, 90) * power; f.t = 0; });
  const burst = (n) => { for (let k = 0; k < n; k++) setTimeout(() => bubble(rnd(0.1, 0.9) * s.W, s.H - 40), k * 55); };
  const splash = () => {
    s.Lv += 0.9;
    const surf = s.H - s.Lc * s.H;
    for (let k = 0; k < 16; k++) push({ k: "d", x: s.W * rnd(0.1, 0.9), y: surf, dx: rnd(-45, 45), h: rnd(60, 150), dur: rnd(0.7, 1.1) });
    scatter(); burst(12);
  };

  // measure
  useEffect(() => {
    const el = cardRef.current; if (!el) return;
    const m = () => { s.W = el.clientWidth; s.H = el.clientHeight; };
    m(); const ro = new ResizeObserver(m); ro.observe(el); return () => ro.disconnect();
  }, [cardRef, s]);
  // fill when scrolled into view
  useEffect(() => { if (!inView) return; const id = setTimeout(() => { s.Lt = level(yearly); }, 350); return () => clearTimeout(id); }, [inView]); // eslint-disable-line
  // billing change → water level, party, treats
  const first = useRef(true);
  useEffect(() => {
    if (first.current) { first.current = false; return; }
    if (s.Lt <= 0) return;
    s.Lt = level(yearly); s.Lv += 0.25; scatter(0.9); burst(8);
    if (yearly) { feed(s.W * 0.35, 0); feed(s.W * 0.65, 0); }
  }, [yearly]); // eslint-disable-line

  // simulation
  const stepRef = useRef();
  stepRef.current = (delta) => {
    let dt = Math.min(0.05, delta / 1000); const now = performance.now() / 1000;
    if (reduce) { s.Lc = s.Lt; dt = 0; }
    else { s.Lv += ((s.Lt - s.Lc) * 38 - s.Lv * 5.5) * dt; s.Lc = Math.max(0, s.Lc + s.Lv * dt); }
    const { W, H } = s; if (!W) return;
    const wh = s.Lc * H; s.water.set(wh);
    const surf = H - wh, top = surf + 14, bot = H - 38;

    let changed = false;
    for (let i = s.foods.length - 1; i >= 0; i--) {
      const d = s.foods[i];
      if (d.dead || d.age > 6) { s.foods.splice(i, 1); changed = true; continue; }
      if (d.y < surf) d.y = surf;
      d.y += d.vy * dt; d.x += Math.sin(now * 3 + d.ph) * 6 * dt;
      if (d.y > H - 34) { d.y = H - 34; d.vy = 0; d.age += dt; }
      d.mx.set(d.x); d.my.set(d.y);
    }
    if (changed) setFoods([...s.foods]);
    if (Math.random() < dt * 1.4) bubble(rnd(20, W - 20), H - 40);

    for (const f of s.fish) {
      f.t -= dt;
      if (f.t <= 0) { f.t = rnd(2, 5.5); f.tx = rnd(15, W - f.w - 15); f.ty = top + Math.random() * Math.max(10, bot - top - f.h); }
      let tx = f.tx, ty = f.ty, urg = 1, food = null, bd = 1e9;
      const mx = f.X + (f.face > 0 ? f.w : 0), my = f.Y + f.h * 0.45;
      if (f.type !== "jelly") for (const g of s.foods) { if (g.dead) continue; const q = Math.hypot(g.x - mx, g.y - my); if (q < bd) { bd = q; food = g; } }
      if (food && bd < 520) {
        tx = food.x - (f.face > 0 ? f.w : 0); ty = food.y - f.h * 0.45; urg = 2.4;
        if (bd < 14) { food.dead = true; animate(f.mv.pop, [1, 1.22, 1], { duration: 0.26 }); bubble(mx, my); }
      } else if (s.cur.a && f.cur) { tx = s.cur.x - f.w / 2; ty = s.cur.y - f.h / 2; urg = 1.25; }
      else if (f.lead) { tx = f.lead.X + f.off[0]; ty = f.lead.Y + f.off[1]; }
      ty = clamp(ty, top, Math.max(top, bot - f.h)); tx = clamp(tx, 6, W - f.w - 6);
      const dx = tx - f.X, dy = ty - f.Y, dd = Math.hypot(dx, dy) || 1;
      const sp = dd > 8 ? f.sp * urg * Math.min(1, dd / 60) : 0, k = 1 - Math.exp(-dt * 2.6);
      f.vx += ((dx / dd) * sp - f.vx) * k; f.vy += ((dy / dd) * sp - f.vy) * k;
      f.X += f.vx * dt; f.Y += f.vy * dt + Math.sin(now * 2.2 + f.ph) * (f.type === "jelly" ? 30 : 8) * dt;
      if (f.X < 4) { f.X = 4; f.vx = Math.abs(f.vx); }
      if (f.X > W - f.w - 4) { f.X = W - f.w - 4; f.vx = -Math.abs(f.vx); }
      if (f.Y < top) f.Y += (top - f.Y) * Math.min(1, dt * 6);
      if (f.Y > bot - f.h) f.Y = bot - f.h;
      if (f.vx > 8) f.face = 1; else if (f.vx < -8) f.face = -1;
      f.fs += (f.face - f.fs) * Math.min(1, dt * 9);
      const ang = f.type === "jelly" ? 0 : clamp((f.vy / (Math.abs(f.vx) + 40)) * 22, -24, 24) * f.face;
      f.mv.x.set(f.X); f.mv.y.set(f.Y); f.mv.rot.set(ang); f.mv.flip.set(f.fs);
      f.mv.op.set(clamp((wh - f.h - 46) / 50, 0, 1));
      if (Math.random() < dt * (f.type === "whale" ? 0.5 : 0.12)) bubble(f.X + (f.face > 0 ? f.w : 0), f.Y + f.h * 0.4);
    }
  };
  useAnimationFrame(useCallback((_, d) => stepRef.current(d), []));

  return { s, fish: s.fish, water: s.water, foods, fx, drop, feed, splash };
}

/* ───────────────────────── small pieces ───────────────────────── */
function Price({ value }) {
  const mv = useMotionValue(value);
  const out = useTransform(mv, (v) => Math.round(v));
  useEffect(() => { const c = animate(mv, value, { duration: 0.7, ease: [0.22, 1, 0.36, 1] }); return () => c.stop(); }, [value, mv]);
  return <motion.b>{out}</motion.b>;
}
const Wave = ({ alt }) => (
  <svg className={"aq-wv" + (alt ? " aq-w2" : "")} viewBox="0 0 400 20" preserveAspectRatio="none">
    <path d="M0 10Q50 0 100 10T200 10T300 10T400 10V20H0Z" />
  </svg>
);
const Weed = ({ style }) => (
  <svg className="aq-weed" style={style} viewBox="0 0 40 90"><path d="M20 90C8 70 28 55 18 36C12 22 24 12 22 2" /></svg>
);
const Check = () => (
  <svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" opacity=".45" /><path d="M8 12.5l2.8 2.8L16 9.8" /></svg>
);

/* A fish with depth: far fish are smaller, dimmer, slightly blurred and shift more
   against the tilt; near fish are bigger, sharper and shift the other way. */
function FishView({ f, shift }) {
  const d = f.depth;
  const par = useTransform(shift, (v) => v * (d - 0.5) * 24);
  return (
    <motion.div className={`aq-fish aq-${f.type}`}
      style={{ width: f.w, x: f.mv.x, y: f.mv.y, rotate: f.mv.rot, opacity: f.mv.op, scale: f.mv.pop, zIndex: Math.round(d * 10) }}>
      <motion.div style={{ x: par, scale: 0.72 + 0.4 * d, opacity: 0.55 + 0.45 * d,
        filter: `blur(${((1 - d) * 1.6).toFixed(2)}px) brightness(${(0.7 + 0.3 * d).toFixed(2)})` }}>
        <motion.div style={{ scaleX: f.mv.flip }}><f.C a={f.a} b={f.b} /></motion.div>
      </motion.div>
    </motion.div>
  );
}

/* ───────────────────────── one tank / plan card ───────────────────────── */
function Tank({ plan, index, yearly, reduce, scale = 1, onSelect }) {
  const cardRef = useRef(null);
  const eng = useTankEngine(cardRef, plan, yearly, reduce);
  const [done, setDone] = useState(false);

  // 3D tilt + water slosh + specular highlight, all springy motion values
  const px = useMotionValue(0.5), py = useMotionValue(0.5);
  const spring = { stiffness: 150, damping: 18 };
  const rotateX = useSpring(useTransform(py, [0, 1], [6, -6]), spring);
  const rotateY = useSpring(useTransform(px, [0, 1], [-6, 6]), spring);
  const slosh = useSpring(useTransform(px, [0, 1], [3.5, -3.5]), { stiffness: 90, damping: 9 });
  const gx = useTransform(px, (v) => v * 100), gy = useTransform(py, (v) => v * 100);
  // depth layers: back wall moves most against the tilt, glass surface/content move with it
  const shift = useTransform(px, [0, 1], [-1, 1]);
  const backX = useTransform(shift, (v) => v * -10), waterX = useTransform(shift, (v) => v * -5), frontX = useTransform(shift, (v) => v * 6);
  const sheen = useMotionTemplate`linear-gradient(115deg,transparent 18%,rgba(255,255,255,.1) 26%,transparent 34%),radial-gradient(340px circle at ${gx}% ${gy}%,rgba(255,255,255,.16),transparent 55%)`;

  const pos = (e) => { const r = cardRef.current.getBoundingClientRect(); return [(e.clientX - r.left) / scale, (e.clientY - r.top) / scale, r]; };
  const onMove = (e) => { const [x, y, r] = pos(e); px.set(x / (r.width / scale)); py.set(y / (r.height / scale)); Object.assign(eng.s.cur, { a: true, x, y }); };
  const onLeave = () => { px.set(0.5); py.set(0.5); eng.s.cur.a = false; };
  const onDown = (e) => { if (e.target.closest(".aq-cta")) return; const [x, y] = pos(e); Object.assign(eng.s.cur, { x, y }); eng.feed(x, y); };
  const click = () => { eng.splash(); setDone(true); setTimeout(() => setDone(false), 1800); onSelect?.(plan, yearly ? "yearly" : "monthly"); };

  return (
    <motion.article
      className={"aq-slot" + (plan.featured ? " aq-f" : "")}
      style={{ "--c": plan.c, "--k": plan.k, "--d": plan.d }}
      initial={reduce ? false : { opacity: 0, y: 28, filter: "blur(8px)" }}
      animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
      transition={{ duration: 0.95, delay: 0.15 + index * 0.13, ease: [0.2, 0.8, 0.2, 1] }}
    >
      <motion.div ref={cardRef} className="aq-card" style={{ rotateX, rotateY, transformPerspective: 1300 }}
        onPointerMove={onMove} onPointerLeave={onLeave} onPointerDown={onDown}>
        <div className="aq-gl" />
        <motion.div className="aq-water" style={{ height: eng.water, rotate: slosh, x: waterX }}><Wave /><Wave alt /></motion.div>
        <motion.div className="aq-back" style={{ x: backX }}><div className="aq-sand" />
        <Weed style={{ left: 26, height: 84, animationDelay: "-1s" }} />
        <Weed style={{ left: 54, height: 62, animationDelay: "-2.4s" }} />
        <Weed style={{ right: 30, height: 76, animationDelay: "-.6s" }} /></motion.div>

        <div className="aq-layer aq-fl">
          {eng.fish.map((f) => <FishView key={f.id} f={f} shift={shift} />)}
        </div>

        <div className="aq-layer aq-fd">
          {eng.foods.map((d) => <motion.i key={d.id} className="aq-pl" style={{ x: d.mx, y: d.my, background: d.col }} />)}
          {eng.fx.map((e) =>
            e.k === "b" ? (
              <motion.i key={e.id} className="aq-b" style={{ left: e.x, top: e.y, width: e.z, height: e.z }}
                initial={{ x: 0, y: 0, opacity: 0.9 }} animate={{ x: e.dx, y: -e.rise, opacity: 0.35 }}
                transition={{ duration: e.dur, ease: "easeIn" }} onAnimationComplete={() => eng.drop(e.id)} />
            ) : e.k === "d" ? (
              <motion.i key={e.id} className="aq-dr" style={{ left: e.x, top: e.y }}
                animate={{ x: [0, e.dx, e.dx * 1.5], y: [0, -e.h, 24], opacity: [1, 1, 0] }}
                transition={{ duration: e.dur, times: [0, 0.45, 1], ease: "easeInOut" }} onAnimationComplete={() => eng.drop(e.id)} />
            ) : (
              <motion.i key={e.id} className="aq-rp" style={{ left: e.x, top: e.y }}
                initial={{ scale: 0.2, opacity: 1 }} animate={{ scale: 2.4, opacity: 0 }}
                transition={{ duration: 0.9, ease: "easeOut" }} onAnimationComplete={() => eng.drop(e.id)} />
            )
          )}
        </div>

        <motion.div className="aq-sheen" style={{ background: sheen }} />
        <div className="aq-lid" />
        <div className="aq-edge" />

        <motion.div className="aq-body" style={{ x: frontX }}>
          <div className="aq-row"><h2>{plan.name}</h2><span className="aq-idx">0{index + 1}</span></div>
          <p className="aq-tag">{plan.tagline}</p>
          {plan.featured && <span className="aq-chip">Most chosen</span>}
          <div className="aq-price"><sup>$</sup><Price value={yearly ? plan.yearly : plan.monthly} /><span>/ mo</span></div>
          <p className="aq-bill">{yearly ? `Billed $${plan.yearly * 12} yearly` : "Billed monthly"}</p>
          <hr />
          <ul>{plan.features.map((f) => <li key={f}><Check />{f}</li>)}</ul>
          <motion.button className="aq-cta" whileHover={{ y: -2 }} whileTap={{ scale: 0.96 }} onClick={click}>
            {done ? "You’re in ✦" : <>{plan.cta} →</>}
          </motion.button>
        </motion.div>
      </motion.div>
    </motion.article>
  );
}

/* ───────────────────────── public component ───────────────────────── */
export default function AquariumPricing({
  plans = DEFAULT_PLANS,
  eyebrow = "Simple, transparent pricing",
  title = <>Dive in, <em>the water’s fine.</em></>,
  lead = "Three tanks, three plans. Tap the water to feed the fish — they’re hungry, and a little nosy.",
  footnote = "14-day free trial on every plan · No card required · Cancel anytime",
  onSelect,
  className = "",
  fitScreen = true, // scale the whole section to fit one screen, centred
}) {
  const [yearly, setYearly] = useState(false);
  const reduce = useReducedMotion();
  const rootRef = useRef(null), fitRef = useRef(null);
  const [scale, setScale] = useState(1);
  useEffect(() => {
    if (!fitScreen) return;
    const root = rootRef.current, inner = fitRef.current; if (!root || !inner) return;
    const calc = () => {
      const vw = root.clientWidth, vh = root.clientHeight;
      if (vw < 900) return setScale(1); // stacked layout: scrolls normally
      setScale(Math.min(1, (vw - 24) / inner.offsetWidth, (vh - 24) / inner.offsetHeight));
    };
    calc();
    const ro = new ResizeObserver(calc); ro.observe(root); ro.observe(inner);
    return () => ro.disconnect();
  }, [fitScreen]);
  return (
    <section ref={rootRef} className={"aq-root " + (fitScreen ? "aq-fit-screen " : "") + className}>
      <div ref={fitRef} className="aq-fit" style={scale < 1 ? { transform: `scale(${scale})` } : undefined}>
      <div className="aq-hero">


        <div className="aq-tog" role="group" aria-label="Billing period">
          {["Monthly", "Yearly"].map((label, i) => {
            const on = yearly === Boolean(i);
            return (
              <button key={label} aria-pressed={on} onClick={() => setYearly(Boolean(i))}>
                {on && <motion.span layoutId="aq-thumb" className="aq-thumb" transition={{ type: "spring", stiffness: 380, damping: 26 }} />}
                <span>{label}</span>{i === 1 && <small>−20%</small>}
              </button>
            );
          })}
        </div>
      </div>
      <div className="aq-plans">
        {plans.map((p, i) => <Tank key={p.name} plan={p} index={i} yearly={yearly} reduce={reduce} scale={scale} onSelect={onSelect} />)}
      </div>
      {footnote && <p className="aq-foot">{footnote}</p>}
      </div>
    </section>
  );
}

@import url("https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Manrope:wght@400;500;600;700&display=swap");

/* Everything is scoped under .aq-root. Override the variables to re-theme. */
.aq-root{--aq-serif:"Instrument Serif","Playfair Display",Georgia,serif;--aq-sans:"Manrope",system-ui,-apple-system,"Segoe UI",sans-serif;--aq-mut:rgba(255,255,255,.72);--aq-line:rgba(255,255,255,.16);
position:relative;overflow:hidden;box-sizing:border-box;padding:28px 24px;min-height:100vh;min-height:100dvh;display:flex;align-items:center;justify-content:center;font-family:var(--aq-sans);color:#fff;-webkit-font-smoothing:antialiased;
background:radial-gradient(80% 55% at 50% -12%,rgba(34,211,238,.3),transparent 62%),radial-gradient(50% 40% at 88% 100%,rgba(124,58,237,.32),transparent),linear-gradient(#04182b,#050c1d 58%,#02040c)}
.aq-root *{box-sizing:border-box;margin:0}
.aq-fit{flex:none;width:1180px;transform-origin:50% 50%}
.aq-fit-screen{height:100vh;height:100dvh}
.aq-root::before{content:"";position:absolute;top:-25%;left:8%;width:18vmax;height:150%;rotate:16deg;background:linear-gradient(180deg,rgba(125,211,252,.2),transparent 70%);filter:blur(10px);pointer-events:none;animation:aq-sw 12s ease-in-out infinite alternate;box-shadow:34vmax 0 0 -2vmax rgba(125,211,252,.12),60vmax 0 0 0 rgba(125,211,252,.1)}
@keyframes aq-sw{to{translate:80px 0;opacity:.55}}

.aq-hero{position:relative;max-width:1180px;margin:0 auto;text-align:center}
.aq-eyebrow{font-size:.76rem;letter-spacing:.22em;text-transform:uppercase;color:var(--aq-mut)}
.aq-hero h1{font-family:var(--aq-serif);font-weight:400;font-size:4rem;line-height:.96;letter-spacing:-.02em;margin:12px 0 14px}
.aq-hero h1 em{background:linear-gradient(100deg,#fff 10%,#67e8f9 60%,#a5b4fc);-webkit-background-clip:text;background-clip:text;color:transparent;padding-right:.08em}
.aq-lead{max-width:440px;margin:0 auto 18px;color:var(--aq-mut);line-height:1.6}

.aq-tog{display:inline-flex;padding:5px;border-radius:99px;background:rgba(255,255,255,.07);border:1px solid var(--aq-line);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.aq-tog button{position:relative;border:0;background:none;color:#fff;font:600 .86rem var(--aq-sans);padding:10px 22px;border-radius:99px;cursor:pointer;display:flex;gap:8px;align-items:center}
.aq-tog button>span,.aq-tog small{position:relative;z-index:1}
.aq-thumb{position:absolute;inset:0;border-radius:99px;background:rgba(255,255,255,.17);border:1px solid rgba(255,255,255,.42)}
.aq-tog small{font-size:.68rem;padding:3px 8px;border-radius:99px;background:rgba(190,242,100,.2);color:#d9f99d;font-weight:700}

.aq-plans{position:relative;max-width:1180px;margin:34px auto 0;display:grid;grid-template-columns:repeat(3,1fr);gap:30px}
.aq-slot{position:relative;display:flex}
.aq-f{translate:0 -22px}
.aq-slot::after{content:"";position:absolute;left:8%;right:8%;bottom:-24px;height:36px;border-radius:50%;background:var(--k);filter:blur(34px);opacity:.5}
.aq-card{position:relative;flex:1;min-height:560px;border-radius:30px;overflow:hidden;z-index:1;cursor:crosshair;box-shadow:0 40px 70px -34px #000}
.aq-gl{position:absolute;inset:0;background:linear-gradient(150deg,rgba(255,255,255,.14),rgba(255,255,255,.02) 45%,rgba(255,255,255,.06));backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}

/* water */
.aq-water{position:absolute;left:-10%;right:-10%;bottom:0;height:0;z-index:2;transform-origin:50% 100%;background:linear-gradient(180deg,color-mix(in srgb,var(--k) 44%,transparent),color-mix(in srgb,var(--d) 78%,transparent))}
.aq-water::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(100deg,transparent 0 30px,rgba(255,255,255,.1) 46px,transparent 70px);-webkit-mask:linear-gradient(#000,transparent 75%);mask:linear-gradient(#000,transparent 75%);animation:aq-rays 9s linear infinite}
.aq-water::after{content:"";position:absolute;inset:0;background:radial-gradient(70px 40px at 20% 30%,rgba(255,255,255,.22),transparent),radial-gradient(90px 50px at 70% 55%,rgba(255,255,255,.16),transparent);mix-blend-mode:screen;animation:aq-caus 7s ease-in-out infinite alternate}
@keyframes aq-rays{to{background-position:140px 0}}@keyframes aq-caus{to{translate:40px 30px}}
.aq-wv{position:absolute;top:-15px;left:0;width:200%;height:18px;fill:color-mix(in srgb,var(--k) 44%,transparent);animation:aq-wv 5s linear infinite}
.aq-w2{top:-12px;opacity:.6;animation-duration:8s;animation-direction:reverse}
@keyframes aq-wv{to{transform:translateX(-50%)}}
.aq-sand{position:absolute;left:0;right:0;bottom:0;height:30px;z-index:3;background:radial-gradient(circle at 20% 60%,rgba(255,255,255,.5) 0 2px,transparent 3px) 0 0/34px 18px,linear-gradient(rgba(240,215,160,.4),rgba(160,120,70,.6))}
.aq-weed{position:absolute;bottom:14px;width:34px;z-index:3;fill:none;stroke:#34d399;stroke-width:4;stroke-linecap:round;opacity:.8;transform-origin:50% 100%;animation:aq-swy 4s ease-in-out infinite alternate}
@keyframes aq-swy{from{rotate:-8deg}to{rotate:9deg}}

/* creatures + effects */
.aq-layer{position:absolute;inset:0;pointer-events:none}.aq-fl{z-index:4}.aq-fd{z-index:5}
.aq-fish{position:absolute;left:0;top:0;will-change:transform}
.aq-fish svg{display:block;width:100%;height:auto;overflow:visible}
.aq-tl{transform-box:fill-box;transform-origin:100% 50%;animation:aq-wag .45s ease-in-out infinite alternate}.aq-whale .aq-tl{animation-duration:1.1s}
@keyframes aq-wag{from{transform:rotate(-16deg)}to{transform:rotate(16deg)}}
.aq-bl,.aq-tt{transform-box:fill-box;transform-origin:50% 0;animation:aq-pls 1.8s ease-in-out infinite}.aq-tt{animation-name:aq-swt}
.aq-jelly svg{filter:drop-shadow(0 0 10px rgba(255,255,255,.55))}
@keyframes aq-pls{50%{transform:scale(1.1,.84)}}@keyframes aq-swt{50%{transform:skewX(9deg) scaleY(1.1)}}
.aq-fp{transform-box:fill-box;transform-origin:85% 15%;animation:aq-flp 1.2s ease-in-out infinite alternate}.aq-f2{animation-delay:-.6s}
@keyframes aq-flp{from{transform:rotate(-18deg)}to{transform:rotate(22deg)}}
.aq-b{position:absolute;border-radius:50%;border:1.3px solid rgba(255,255,255,.8);background:radial-gradient(circle at 30% 30%,rgba(255,255,255,.7),transparent 60%)}
.aq-pl{position:absolute;left:0;top:0;width:7px;height:7px;border-radius:50%;box-shadow:0 0 8px #f59e0b}
.aq-rp{position:absolute;width:60px;height:12px;margin:-6px 0 0 -30px;border:2px solid rgba(255,255,255,.85);border-radius:50%}
.aq-dr{position:absolute;width:7px;height:9px;border-radius:50% 50% 50% 50%/60% 60% 40% 40%;background:rgba(255,255,255,.85)}

/* glass finish */
.aq-sheen{position:absolute;inset:0;z-index:6;border-radius:inherit;pointer-events:none}
.aq-sheen::before{content:"";position:absolute;inset:0;border-radius:inherit;padding:1.3px;background:linear-gradient(140deg,rgba(255,255,255,.95),rgba(255,255,255,.05) 30%,rgba(255,255,255,.05) 68%,rgba(255,255,255,.6));-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);mask-composite:exclude}
.aq-lid{position:absolute;top:0;left:14%;right:14%;height:3px;z-index:7;border-radius:0 0 6px 6px;background:linear-gradient(90deg,transparent,var(--c),transparent);box-shadow:0 0 26px 6px var(--c)}

/* depth: back wall, glass thickness, ground shadow */
.aq-back{position:absolute;inset:0 -12px;z-index:3;pointer-events:none}
.aq-edge{position:absolute;inset:0;border-radius:inherit;z-index:9;pointer-events:none;box-shadow:inset 0 0 0 1px rgba(255,255,255,.28),inset 7px 7px 16px -6px rgba(255,255,255,.38),inset -8px -9px 18px -6px rgba(0,0,0,.5),inset 0 -30px 44px -28px color-mix(in srgb,var(--k) 75%,transparent)}
.aq-edge::after{content:"";position:absolute;inset:7px;border-radius:24px;border:1px solid rgba(255,255,255,.12);box-shadow:inset 0 1px 0 rgba(255,255,255,.18)}
.aq-slot::before{content:"";position:absolute;left:6%;right:6%;bottom:-34px;height:24px;border-radius:50%;background:#000;filter:blur(18px);opacity:.6}

/* content */
.aq-body{position:relative;z-index:8;pointer-events:none;display:flex;flex-direction:column;height:100%;min-height:560px;padding:30px 28px 26px;text-shadow:0 1px 10px rgba(3,10,30,.65)}
.aq-row{display:flex;justify-content:space-between;align-items:baseline}
.aq-body h2{font-family:var(--aq-serif);font-weight:400;font-size:2.2rem;line-height:1}
.aq-idx{font-size:.72rem;letter-spacing:.2em;color:var(--aq-mut)}
.aq-tag{color:var(--aq-mut);font-size:.9rem;margin-top:6px}
.aq-chip{align-self:flex-start;margin-top:14px;font-size:.68rem;letter-spacing:.14em;text-transform:uppercase;font-weight:700;padding:6px 12px;border-radius:99px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.45)}
.aq-price{display:flex;align-items:flex-start;gap:4px;margin-top:22px;line-height:.85}
.aq-price sup{font-size:1.5rem;margin-top:8px;color:var(--aq-mut)}
.aq-price b{font-family:var(--aq-serif);font-weight:400;font-size:4.4rem;letter-spacing:-.03em;font-variant-numeric:tabular-nums;text-shadow:0 0 40px var(--c),0 2px 12px rgba(0,0,0,.4)}
.aq-price span{align-self:flex-end;margin-bottom:9px;color:var(--aq-mut);font-size:.9rem}
.aq-bill{color:var(--aq-mut);font-size:.8rem;margin-top:8px;min-height:1.1em}
.aq-body hr{border:0;height:1px;background:var(--aq-line);margin:18px 0 4px}
.aq-body ul{list-style:none;padding:0;flex:1;margin-bottom:20px}
.aq-body li{display:flex;gap:12px;align-items:center;padding:8px 0;font-size:.92rem;font-weight:500}
.aq-body li+li{border-top:1px solid rgba(255,255,255,.08)}
.aq-body li svg{flex:none;width:18px;height:18px;stroke:var(--c);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.aq-cta{pointer-events:auto;border-radius:16px;height:54px;width:100%;font:700 .96rem var(--aq-sans);color:#fff;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:10px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.5);box-shadow:inset 0 1px 0 rgba(255,255,255,.4);text-shadow:none}
.aq-cta:hover{background:rgba(255,255,255,.2)}
.aq-f .aq-cta{background:#fff;color:#08142b;border-color:#fff;box-shadow:0 18px 40px -12px var(--c)}
.aq-foot{position:relative;text-align:center;color:var(--aq-mut);font-size:.82rem;margin-top:26px}

@media (max-width:899px){.aq-root{height:auto!important;display:block;padding:40px 18px 56px}.aq-fit{width:100%;max-width:420px;margin:0 auto}.aq-hero h1{font-size:2.8rem}.aq-plans{grid-template-columns:1fr;gap:44px}.aq-f{translate:0 0}}
@media (prefers-reduced-motion:reduce){.aq-root *{animation:none!important}}
